const free = CW - gap * (blocks.length - 1);
const graphic = [], grid = [], xAxis = [], yAxis = [], series = [];
let tooltip;
let x = 0;
blocks.forEach((b) => {
  const cw = CW ? (free * b.weight) / totalW : 0;
  graphic.push(surface(x, cw, CH));
  if (b.id === 'requests') {
    graphic.push(label(x + 16, 12, 'Requests per hour', cw * 0.4));
    const parts = [];
    if (edgeOk) parts.push('{e|●} edge ' + count(edgeTotal));
    if (hasOrigin && originTotal !== null) parts.push('{o|●} origin ' + count(originTotal));
    graphic.push({ type: 'text', right: CW - x - cw + 16, top: 11, silent: true,
      style: { text: parts.join('   '), fill: '#C9D2DE', font: '12px ' + MONO, align: 'right',
        rich: { e: { fill: '#60A5FA', font: '12px ' + MONO }, o: { fill: '#C4B5FD', font: '12px ' + MONO } } } });
    grid.push({ left: x + 52, top: 40, width: Math.max(10, cw - 72), height: Math.max(20, CH - 40 - 30) });
    xAxis.push({ type: 'time', gridIndex: 0, min: START, max: to,
      axisLine: { lineStyle: { color: '#1F2733' } }, axisTick: { show: false }, splitLine: { show: false },
      axisLabel: { color: '#8D99AB', fontFamily: MONO, fontSize: 10, hideOverlap: true } });
    yAxis.push({ type: 'value', gridIndex: 0, min: 0, minInterval: 1, splitNumber: 3,
      splitLine: { lineStyle: { color: '#1F2733' } },
      axisLabel: { color: '#8D99AB', fontFamily: MONO, fontSize: 10,
        formatter: (v) => (v >= 1000 ? +(v / 1000).toFixed(1) + 'k' : String(v)) } });
    const few = edgeSeries.length <= 24;
    if (edgeOk) series.push({ name: 'edge', type: 'line', data: edgeSeries, showSymbol: few, symbolSize: 4,
      connectNulls: false, lineStyle: { width: 2, color: '#60A5FA' }, itemStyle: { color: '#60A5FA' } });
    if (hasOrigin) series.push({ name: 'origin', type: 'line', data: originSeries, showSymbol: few, symbolSize: 4,
      connectNulls: false, lineStyle: { width: 2, color: '#C4B5FD' }, itemStyle: { color: '#C4B5FD' } });
    tooltip = Object.assign({ trigger: 'axis', axisPointer: { type: 'line', lineStyle: { color: '#1F2733' } },
      formatter: (ps) => hourLabel(ps[0].value[0]) + ', ' + stepWord + '<br/>' + ps.map((p) => p.marker + p.seriesName + ' '
        + perHour(p.value[1])).join('<br/>') }, TIP);
  } else if (b.id === 'stats') {
    const half = CH / 2;
    const fit = { width: Math.max(10, cw - 32), overflow: 'truncate', ellipsis: '…' };
    const share = edgeTotal ? e5 / edgeTotal : null;
    const colour = share === null ? '#8D99AB' : share >= 0.05 ? '#FB7185' : share >= 0.01 ? '#FBBF24' : '#E7ECF3';
    graphic.push(label(x + 16, 12, '5xx at the edge', cw - 32));
    graphic.push({ type: 'text', left: x + 16, top: 28, silent: true,
      style: { text: '{v|' + (share === null ? '—' : pct(share)) + '}' + (share === null ? '' : '{u| %}'),
        rich: { v: { fill: colour, font: '600 26px ' + MONO }, u: { fill: '#8D99AB', font: '13px ' + MONO, padding: [10, 0, 0, 2] } } } });
    graphic.push({ type: 'text', left: x + 16, top: 64, silent: true,
      style: Object.assign({ text: edgeTotal ? count(e5) + ' of ' + count(edgeTotal) : 'no requests', fill: '#8D99AB', font: '12px ' + MONO }, fit) });
    graphic.push({ type: 'line', silent: true, shape: { x1: x + 16, y1: half, x2: x + cw - 16, y2: half }, style: { stroke: '#1F2733', lineWidth: 1 } });
    graphic.push(label(x + 16, half + 12, 'WAF blocked', cw - 32));
    graphic.push({ type: 'text', left: x + 16, top: half + 28, silent: true,
      style: { text: '{v|' + count(stopped.length) + '}', rich: { v: { fill: '#E7ECF3', font: '600 26px ' + MONO } } } });
    graphic.push({ type: 'text', left: x + 16, top: half + 64, silent: true,
      style: Object.assign({ text: mostly ? 'mostly ' + source(mostly[0]) : events.length ? count(events.length) + ' logged, none blocked' : 'none in ' + span,
        fill: '#8D99AB', font: '12px ' + MONO }, fit) });
  } else if (b.id === 'countries') {
    graphic.push(label(x + 16, 12, 'Top countries', cw - 32));
    if (!top.length) {
      graphic.push({ type: 'text', left: x + 16, top: 40, silent: true, style: { text: 'no requests in ' + span, fill: '#8D99AB', font: '12px ' + MONO } });
    }
    const rowH = Math.min(34, (CH - 44) / Math.max(top.length, 1));
    const bw = cw - 32;
    top.forEach(([code, n], i) => {
      const y = 38 + i * rowH;
      const share = edgeTotal ? n / edgeTotal : 0;
      graphic.push({ type: 'text', left: x + 16, top: y, silent: true,
        style: { text: country(code), fill: '#C9D2DE', font: '12px Inter, sans-serif', width: bw - 56, overflow: 'truncate', ellipsis: '…' } });
      graphic.push({ type: 'text', right: CW - x - cw + 16, top: y, silent: true,
        style: { text: Math.round(share * 100) + ' %', fill: '#8D99AB', font: '12px ' + MONO, align: 'right' } });
      graphic.push({ type: 'rect', left: x + 16, top: y + 17, silent: true, shape: { width: bw, height: 5, r: 3 }, style: { fill: 'rgba(96,165,250,.14)' } });
      graphic.push({ type: 'rect', left: x + 16, top: y + 17, shape: { width: Math.max(3, share * bw), height: 5, r: 3 }, style: { fill: '#60A5FA' },
        info: country(code) + ': ' + count(n) });
    });
  } else if (b.id === 'tunnels') {
    graphic.push(label(x + 16, 12, 'Tunnels', cw - 32));
    const rowH = (CH - 40) / tunnels.length;
    tunnels.forEach((t, i) => {
      const y = 36 + i * rowH;
      const worst = t.list.some((c) => c.state === 'down') ? 'down' : t.list.some((c) => c.state === 'short') ? 'short' : 'ok';
      const word = worst === 'ok' ? '● up' : worst === 'short' ? '▲ short' : '✕ down';
      graphic.push({ type: 'text', left: x + 16, top: y + 4, silent: true, style: { text: t.name, fill: '#E7ECF3', font: '600 13px Inter, sans-serif' } });
      graphic.push({ type: 'text', right: CW - x - cw + 16, top: y + 4, silent: true,
        style: { text: word, fill: STATE[worst], font: '12px ' + MONO, align: 'right' } });
      const colW = (cw - 32) / Math.max(2, t.list.length);
      t.list.forEach((c, j) => {
        const cx = x + 16 + j * colW;
        graphic.push({ type: 'circle', left: cx, top: y + 28, shape: { r: 6 }, style: { fill: STATE[c.state] },
          info: c.host + ': ' + c.ha + ' of 4 connections' + (c.up === 0 ? ', target down' : '') });
        graphic.push({ type: 'text', left: cx + 18, top: y + 26, silent: true,
          style: { text: String(c.host).replace(/^vm-/, ''), fill: '#C9D2DE', font: '12px ' + MONO, width: colW - 22, overflow: 'truncate', ellipsis: '…' } });
        graphic.push({ type: 'text', left: cx + 18, top: y + 42, silent: true,
          style: { text: c.up === 0 ? 'target down' : c.ha + ' of 4', fill: STATE[c.state], font: '11px ' + MONO, width: colW - 22, overflow: 'truncate', ellipsis: '…' } });
      });
    });
  }
  x += cw + gap;
});
return { backgroundColor: 'transparent', animation: false, graphic, grid, xAxis, yAxis, series, tooltip };

