options.getOption:
const SHADES = {
  infra: ['#7DD3FC', '#38BDF8', '#0EA5E9', '#0284C7', '#0369A1'],
  apps: ['#FBBF24', '#F59E0B', '#D97706', '#B45309', '#92400E'],
  sandbox: ['#C4B5FD', '#A78BFA', '#8B5CF6', '#7C3AED', '#6D28D9'],
};
const TOP = 4;
const tree = {};
let total = 0;
for (const s of context.panel.data.series) {
  const pool = s.fields.find((f) => f.name === 'pool');
  const ns = s.fields.find((f) => f.name === 'namespace');
  const v = s.fields.find((f) => f.type === 'number');
  if (!ns || !v) continue;
  for (let i = 0; i < v.values.length; i++) {
    const p = (pool && pool.values[i]) || 'no pool';
    (tree[p] = tree[p] || []).push({ name: ns.values[i], value: v.values[i] });
    total += v.values[i];
  }
}
if (!total) {
  return { title: { text: 'No memory reported in this range', left: 'center', top: 'middle',
    textStyle: { color: '#8D99AB', fontSize: 13, fontWeight: 'normal' } } };
}
const gib = (b) => (b / 2 ** 30).toFixed(1) + ' GiB';
const order = ['infra', 'apps', 'sandbox'];
const pools = Object.keys(tree).sort((a, b) => (order.indexOf(a) + 9) % 9 - (order.indexOf(b) + 9) % 9);
const legend = [];
const data = pools.map((p) => {
  const shades = SHADES[p] || ['#8D99AB', '#7C8798', '#6B7585', '#5A6372', '#49515F'];
  const list = tree[p].sort((a, b) => b.value - a.value);
  const top = list.slice(0, TOP).map((k, i) => {
    legend.push({ name: k.name, value: k.value, colour: shades[i] });
    return { name: k.name, value: k.value, itemStyle: { color: shades[i] } };
  });
  const rest = list.slice(TOP).reduce((s, k) => s + k.value, 0);
  if (rest > 0) top.push({ name: 'other in ' + p, value: rest, itemStyle: { color: '#334155' } });
  return { name: p, itemStyle: { color: shades[0] }, children: top };
});
const W = context.panel.chart.getWidth();
const H = context.panel.chart.getHeight();
const MONO = "'JetBrains Mono', 'Roboto Mono', monospace";
const graphic = [{ type: 'text', left: 'center', top: H * 0.29 - 20,
  style: { text: (total / 2 ** 30).toFixed(1) + '\nGiB', fill: '#E7ECF3', align: 'center',
    font: '600 16px ' + MONO, lineHeight: 20 } }];
const listed = order.concat(pools.filter((p) => order.indexOf(p) < 0));
const lineH = 17;
const PER = 2;
let y = H - 8 - listed.reduce((s, p) => s + lineH + 4 + Math.min(PER, (tree[p] || []).length) * lineH, 0);
listed.forEach((p) => {
  const list = tree[p] || [];
  const sum = list.reduce((s, k) => s + k.value, 0);
  const shades = SHADES[p] || ['#8D99AB', '#7C8798', '#6B7585', '#5A6372', '#49515F'];
  graphic.push({ type: 'circle', left: 6, top: y + 4, shape: { r: 4 }, style: { fill: shades[0] } });
  graphic.push({ type: 'text', left: 18, top: y, style: { text: p.toUpperCase(), fill: '#8D99AB',
    font: '600 11px Inter, sans-serif' } });
  graphic.push({ type: 'text', right: 6, top: y, style: { text: list.length ? gib(sum) : '—', fill: '#E7ECF3',
    font: '12px ' + MONO } });
  y += lineH;
  list.slice(0, PER).forEach((k, i) => {
    graphic.push({ type: 'text', left: 18, top: y, style: { text: k.name, fill: '#C9D2DE',
      font: '12px Inter, sans-serif', width: W - 110, overflow: 'truncate', ellipsis: '…' } });
    graphic.push({ type: 'text', right: 6, top: y, style: { text: gib(k.value), fill: '#C9D2DE',
      font: '12px ' + MONO } });
    y += lineH;
  });
  y += 4;
});
return {
  backgroundColor: 'transparent',
  tooltip: { trigger: 'item', formatter: (p) => {
    const pool = p.treePathInfo && p.treePathInfo.length > 2 ? p.treePathInfo[1].name + ' · ' : '';
    return pool + p.name + ': ' + gib(p.value);
  } },
  graphic,
  series: [{
    type: 'sunburst', center: ['50%', '29%'], radius: ['16%', '42%'], data, sort: null,
    itemStyle: { borderColor: '#111217', borderWidth: 2 },
    levels: [{},
      { r0: '16%', r: '28%', label: { show: false } },
      { r0: '28%', r: '42%', label: { show: false } }],
  }],
};
